import sys
import json
import pandas as pd
import numpy as np

def to_float(x, nd=2):
    return round(float(x), nd)

def main():
    path = sys.argv[1]
    df = pd.read_csv(path)

    facts = []

    # ---------- TOTAL level aggregates ----------
    rev_tw_sum = df['Revenue_TW'].sum(skipna=True)
    rev_lw_sum = df['Revenue_LW'].sum(skipna=True)
    rev_ly_sum = df['Revenue_LY'].sum(skipna=True) if df['Revenue_LY'].notna().any() else np.nan
    units_tw_sum = df['Units_TW'].sum(skipna=True)
    units_lw_sum = df['Units_LW'].sum(skipna=True)
    orders_tw_sum = df['Orders_TW'].sum(skipna=True)
    orders_lw_sum = df['Orders_LW'].sum(skipna=True)

    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "TW",
        "value": to_float(rev_tw_sum),
        "formula": "sum(Revenue_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "LW",
        "value": to_float(rev_lw_sum),
        "formula": "sum(Revenue_LW)"
    })
    if not np.isnan(rev_ly_sum):
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "LY",
            "value": to_float(rev_ly_sum),
            "formula": "sum(Revenue_LY)"
        })

    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "TW",
        "value": to_float(units_tw_sum, 0),
        "formula": "sum(Units_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "LW",
        "value": to_float(units_lw_sum, 0),
        "formula": "sum(Units_LW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "TW",
        "value": to_float(orders_tw_sum, 0),
        "formula": "sum(Orders_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "LW",
        "value": to_float(orders_lw_sum, 0),
        "formula": "sum(Orders_LW)"
    })

    if rev_lw_sum and not np.isnan(rev_lw_sum) and rev_lw_sum != 0:
        total_wow = (rev_tw_sum - rev_lw_sum) / rev_lw_sum * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "WoW",
            "value": to_float(total_wow, 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LW)) / sum(Revenue_LW) * 100"
        })

    if not np.isnan(rev_ly_sum) and rev_ly_sum != 0:
        total_yoy = (rev_tw_sum - rev_ly_sum) / rev_ly_sum * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "YoY",
            "value": to_float(total_yoy, 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LY)) / sum(Revenue_LY) * 100"
        })

    # ---------- Top entities by revenue TW (rank) ----------
    top_rev = df.dropna(subset=['Revenue_TW']).sort_values('Revenue_TW', ascending=False).head(5)
    for _, row in top_rev.iterrows():
        facts.append({
            "entity": row['Entity'], "metric": "revenue", "period": "TW",
            "value": to_float(row['Revenue_TW']),
            "formula": "Revenue_TW"
        })

    # ---------- Top Share leaders ----------
    top_share = df.dropna(subset=['Share_Pct']).sort_values('Share_Pct', ascending=False).head(3)
    for _, row in top_share.iterrows():
        facts.append({
            "entity": row['Entity'], "metric": "share", "period": "TW",
            "value": to_float(row['Share_Pct'], 1),
            "formula": "Share_Pct"
        })

    # ---------- Top WoW gainers / decliners ----------
    wow_valid = df.dropna(subset=['WoW_Pct'])
    top_wow_gain = wow_valid.sort_values('WoW_Pct', ascending=False).head(3)
    for _, row in top_wow_gain.iterrows():
        facts.append({
            "entity": row['Entity'], "metric": "revenue", "period": "WoW",
            "value": to_float(row['WoW_Pct'], 1),
            "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
        })

    top_wow_decline = wow_valid.sort_values('WoW_Pct', ascending=True).head(3)
    for _, row in top_wow_decline.iterrows():
        facts.append({
            "entity": row['Entity'], "metric": "revenue", "period": "WoW",
            "value": to_float(row['WoW_Pct'], 1),
            "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
        })

    # ---------- Top YoY gainers / decliners ----------
    yoy_valid = df.dropna(subset=['YoY_Pct'])
    if not yoy_valid.empty:
        top_yoy_gain = yoy_valid.sort_values('YoY_Pct', ascending=False).head(3)
        for _, row in top_yoy_gain.iterrows():
            facts.append({
                "entity": row['Entity'], "metric": "revenue", "period": "YoY",
                "value": to_float(row['YoY_Pct'], 1),
                "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100"
            })

        top_yoy_decline = yoy_valid.sort_values('YoY_Pct', ascending=True).head(3)
        for _, row in top_yoy_decline.iterrows():
            facts.append({
                "entity": row['Entity'], "metric": "revenue", "period": "YoY",
                "value": to_float(row['YoY_Pct'], 1),
                "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100"
            })

    # ---------- Rank 1 entity ----------
    rank1 = df.dropna(subset=['Rank']).sort_values('Rank').head(1)
    for _, row in rank1.iterrows():
        facts.append({
            "entity": row['Entity'], "metric": "rank", "period": "TW",
            "value": to_float(row['Rank'], 0),
            "formula": "Rank"
        })

    # Trim to max 25 facts
    facts = facts[:25]

    # Ensure all values are plain python floats/ints
    for f in facts:
        if isinstance(f['value'], (np.floating, np.integer)):
            f['value'] = float(f['value'])
        else:
            f['value'] = float(f['value'])

    print(json.dumps(facts))

if __name__ == "__main__":
    main()
